import React, { useState, useEffect } from 'react';
import orderService from '../services/orderService';

const ReadyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [fadeOutOrders, setFadeOutOrders] = useState(new Set());
  const [scaleInOrders, setScaleInOrders] = useState(new Set());

  useEffect(() => {
    // Initial load
    setOrders(orderService.getReadyOrders());

    // Set up automatic updates every 3 seconds
    const interval = setInterval(() => {
      const previousOrderIds = orders.map(order => order.id);

      // Simulate order updates
      orderService.simulateOrderUpdates();
      const newOrders = orderService.getReadyOrders();
      const currentOrderIds = newOrders.map(order => order.id);

      // Find orders that were removed
      const removedOrderIds = orderService.getRemovedOrders(currentOrderIds, previousOrderIds);

      // Find new orders
      const newOrderIds = currentOrderIds.filter(id => !previousOrderIds.includes(id));

      if (removedOrderIds.length > 0) {
        // Start fade out animation for removed orders
        setFadeOutOrders(new Set(removedOrderIds));

        // Remove orders after fade animation completes
        setTimeout(() => {
          setOrders(newOrders);
          setFadeOutOrders(new Set());
        }, 500); // 500ms fade duration
      } else {
        // Just update orders if no removals
        setOrders(newOrders);
      }

      // Handle new orders with scale-in animation
      if (newOrderIds.length > 0) {
        setScaleInOrders(new Set(newOrderIds));
        setTimeout(() => {
          setScaleInOrders(new Set());
        }, 600); // 600ms scale duration
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [orders]);

  return (
    <div className="w-full h-full flex flex-col">
      {/* Header */}
      <div className="text-center mb-8">
        <h1 className="text-4xl xl:text-8xl font-bold text-black">
          READY ORDERS
        </h1>
      </div>

      {/* Token Grid - 2 columns × 4 rows (max 8 tokens) */}
      <div className="flex-1 grid grid-cols-2 grid-rows-4 gap-6 xl:gap-8">
        {Array.from({ length: 8 }, (_, index) => {
          const order = orders[index];
          const isFadingOut = order && fadeOutOrders.has(order.id);
          const isScalingIn = order && scaleInOrders.has(order.id);

          return (
            <div 
              key={order ? order.id : `empty-${index}`}
              className={`bg-white border-4 border-gray-300 rounded-xl shadow-lg flex items-center justify-center token-card ${
                isFadingOut 
                  ? 'fade-out' 
                  : isScalingIn 
                    ? 'scale-in' 
                    : 'normal'
              }`}
            >
              {order ? (
                <div className="token-number text-black text-center">
                  {order.tokenNumber}
                </div>
              ) : (
                <div className="token-number text-gray-200 text-center">
                  ---
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ReadyOrders;
